 }
 ~GLReference(){for(auto [name,id]:textures)glDeleteTextures(1,&id);glDeleteRenderbuffersEXT(1,&attachment);glDeleteFramebuffersEXT(1,&fbo);CGLSetCurrentContext(nullptr);if(context)CGLDestroyContext(context);if(format)CGLDestroyPixelFormat(format);}
 void bind(const std::string& key,const Texture& t){auto it=textures.find(key);if(it!=textures.end()){glBindTexture(GL_TEXTURE_2D,it->second);return;}int pw=nextPOT(t.w),ph=nextPOT(t.h);GLuint id;glGenTextures(1,&id);glBindTexture(GL_TEXTURE_2D,id);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);
  if(t.format==SpriteTextureFormat::RGB565){std::vector<uint16_t> pixels(pw*ph);for(int y=0;y<t.h;++y)for(int x=0;x<t.w;++x){size_t i=(y*t.w+x)*4;pixels[y*pw+x]=uint16_t((t.pixels[i]>>3)<<11|(t.pixels[i+1]>>2)<<5|(t.pixels[i+2]>>3));}glTexImage2D(GL_TEXTURE_2D,0,GL_RGB,pw,ph,0,GL_RGB,GL_UNSIGNED_SHORT_5_6_5,pixels.data());}
