 void blend(int mode,bool trail){require(mode==0||mode==2||mode==3,"unsupported blend");glBlendFunc(GL_SRC_ALPHA,(mode==2||(trail&&mode==3))?GL_ONE:GL_ONE_MINUS_SRC_ALPHA);}
 std::vector<uint8_t> draw(const Frame& f,Cache& cache){glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT);
  for(auto& item:f.items){glLoadIdentity();if(auto* d=std::get_if<DrawSprite>(&item)){auto& t=cache.get(d->tile);bind(d->tile,t);blend(d->blend,false);float w=float(t.w)/d->cols,h=float(t.h)/d->rows,u=w/nextPOT(t.w),v=h/nextPOT(t.h);int tile=std::min(d->frame,d->cols*d->rows-1);float u0=(tile%d->cols)*u,v0=(tile/d->cols)*v;GLfloat vertices[]={-w/2,-h/2,w/2,-h/2,-w/2,h/2,w/2,h/2},uv[]={u0,v0+v,u0+u,v0+v,u0,v0,u0+u,v0},color[]={1,1,1,d->alpha,1,1,1,d->alpha,1,1,1,d->alpha,1,1,1,d->alpha};glTranslatef(d->position.x,d->position.y,0);glScalef(d->scale.x,d->scale.y,1);glRotatef(float(double(d->rotation)*57.29577951308232),0,0,1);glVertexPointer(2,GL_FLOAT,0,vertices);glTexCoordPointer(2,GL_FLOAT,0,uv);glColorPointer(4,GL_FLOAT,0,color);glDrawArrays(GL_TRIANGLE_STRIP,0,4);
